  "content": "package com.esf.service.mapper;

import com.esf.service.entity.User;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

/**
 * MyBatis mapper for the {@code users} table. Discovered by Spring Boot
 * auto-configuration through the {@code @Mapper} annotation.
 */
@Mapper
public interface UserMapper {

    /**
     * Reads one user by {@code username}, or null when no such account exists.
     */
    @Select("SELECT * FROM users WHERE username = #{username}")
    User findByUsername(@Param("username") String username);

    /**
     * Stores a user and writes the generated primary key back onto {@code id}.
     */
    @Insert("INSERT INTO users (username, password, role, created_at) "
            + "VALUES (#{username}, #{password}, #{role}, #{createdAt})")
    @Options(useGeneratedKeys = true, keyProperty = "id")
    int insert(User user);

    /**
     * Counts the rows in the table; used to guard startup seeding.
     */
    @Select("SELECT COUNT(*) FROM users")
    long count();
}
"
}

