import java.util.Map;

/**
 * Publishes {@code POST /api/departments} and {@code GET /api/departments},
 * reading the create body as a string map and the optional {@code orgId}
 * query parameter, and delegating to {@link DepartmentService}. The listing
 * route's payload is a plain JSON array of departments — not a page object.
 */
@RestController
@RequestMapping("/api/departments")
public class DepartmentController {

    private final DepartmentService departmentService;

    public DepartmentController(DepartmentService departmentService) {
        this.departmentService = departmentService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Department>> create(@RequestBody Map<String, String> body) {
        Department department = departmentService.createDepartment(body.get("name"), body.get("orgId"));
        return ResponseEntity.ok(ApiResponse.success("创建成功", department));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Department>>> list(@RequestParam(required = false) String orgId) {
        List<Department> departments = departmentService.listDepartments(orgId);
        return ResponseEntity.ok(ApiResponse.success("查询成功", departments));
    }
}

package com.esf.service.controller;

import com.esf.service.dto.ApiResponse;
import com.esf.service.dto.PageResult;
import com.esf.service.dto.ServiceOrderRequest;
import com.esf.service.dto.ServiceQueryParams;
import com.esf.service.entity.ServiceOrder;
import com.esf.service.service.ServiceOrderService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

/**
 * Publishes the five order routes: {@code POST /api/services},
 * {@code GET /api/services}, {@code GET /api/services/{id}},
 * {@code PUT /api/services/{id}/status} and {@code GET /api/services/stats}.
 * Collects the eight listing query parameters into a {@link ServiceQueryParams}
 * instance, delegates to {@link ServiceOrderService}, and maps a missing order
 * to the 404 envelope on the two by-id routes.
 */
@RestController
@RequestMapping("/api/services")
public class ServiceOrderController {

    private final ServiceOrderService serviceOrderService;

    public ServiceOrderController(ServiceOrderService serviceOrderService) {
        this.serviceOrderService = serviceOrderService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<ServiceOrder>> create(@RequestBody ServiceOrderRequest request) {
        ServiceOrder order = serviceOrderService.createOrder(request);
        return ResponseEntity.ok(ApiResponse.success("创建成功", order));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<PageResult<ServiceOrder>>> list(
            @RequestParam(required = false) String type,
            @RequestParam(required = false) String typeValue,
            @RequestParam(required = false) String orgId,
            @RequestParam(required = false) String departmentId,
            @RequestParam(required = false) String skillGroupId,
            @RequestParam(required = false) String status,
            @RequestParam(required = false) Integer current,
            @RequestParam(required = false) Integer size) {
        ServiceQueryParams params = new ServiceQueryParams();
        params.setType(type);
        params.setTypeValue(typeValue);
        params.setOrgId(orgId);
        params.setDepartmentId(departmentId);
        params.setSkillGroupId(skillGroupId);
        params.setStatus(status);
        if (current != null) {
            params.setCurrent(current);
        }
        if (size != null) {
            params.setSize(size);
        }
        PageResult<ServiceOrder> page = serviceOrderService.queryOrders(params);
        return ResponseEntity.ok(ApiResponse.success("查询成功", page));
    }

    @GetMapping("/stats")
    public ResponseEntity<ApiResponse<Map<String, Object>>> stats(@RequestParam(required = false) String orgId) {
        Map<String, Object> stats = serviceOrderService.getStatistics(orgId);
        return ResponseEntity.ok(ApiResponse.success("查询成功", stats));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<ServiceOrder>> getById(@PathVariable Long id) {
        ServiceOrder order = serviceOrderService.getOrderById(id);
        if (order == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(HttpStatus.NOT_FOUND.value(), "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("查询成功", order));
    }

    @PutMapping("/{id}/status")
    public ResponseEntity<ApiResponse<Map<String, Object>>> updateStatus(
            @PathVariable Long id,
            @RequestBody Map<String, String> body) {
        Map<String, Object> result = serviceOrderService.updateOrderStatus(id, body.get("status"), body.get("owner"));
        if (result == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.error(HttpStatus.NOT_FOUND.value(), "工单不存在"));
        }
        return ResponseEntity.ok(ApiResponse.success("更新成功", result));
    }
}

package com.esf.service.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Generic response envelope. Every route answers with the three JSON keys
 * {@code code}, {@code message} and {@code data}.
 *
 * @param <T> the payload type carried in {@code data}
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ApiResponse<T> {

    private int code;

    private String message;

    private T data;

    /**
     * Builds a successful envelope carrying {@code code} 200.
     */
    public static <T> ApiResponse<T> success(String message, T data) {
        return ApiResponse.<T>builder()
                .code(200)
                .message(message)
                .data(data)
                .build();
    }

    /**
     * Builds a failure envelope carrying the given non-200 code and a null payload.
     */
    public static <T> ApiResponse<T> error(int code, String message) {
        return ApiResponse.<T>builder()
                .code(code)
                .message(message)
                .data(null)
                .build();
    }
}

